function Icon({ name, size = 20 }) {
  const p = {width:size,height:size,viewBox:"0 0 24 24",fill:"none",stroke:"currentColor",strokeWidth:1.7,strokeLinecap:"round",strokeLinejoin:"round","aria-hidden":true};
  if(name==="arrow") return <svg {...p}><path d="M5 12h14"/><path d="m14 7 5 5-5 5"/></svg>;
  if(name==="search") return <svg {...p}><circle cx="11" cy="11" r="6.5"/><path d="m16 16 4.2 4.2"/></svg>;
  if(name==="target") return <svg {...p}><circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="3"/></svg>;
  if(name==="layers") return <svg {...p}><path d="m12 3 9 5-9 5-9-5z"/><path d="m3 12 9 5 9-5M3 16l9 5 9-5"/></svg>;
  return <svg {...p}><path d="m5 12 4 4L19 6"/></svg>;
}

function ExternalLink({href,children}) { return <a className="text-link" href={href} target="_blank" rel="noreferrer"><span>{children}</span><Icon name="arrow" size={16}/></a>; }

